// Original bounded sources; design references and limits are recorded in spec223 and its signed/zero catalog extension312.
export const linearChallenges=[['revisit','Find an output'],['unknown','Find an input'],['contrast','Compare two rules']];
const q=v=>{let n=Math.round(v*2),d=2;while(d>1&&n%2===0){n/=2;d/=2;}return d===1?String(n):`${n}/${d}`;};
const f=(id,label,answer)=>({id,label,answer:q(answer)});
const item=(id,page,prompt,fields,guidance,hint,example,explanation)=>({id,page,prompt,fields,guidance,hint,example,explanation});
export function generatedLinearSource(serial,challenge){
 if(!Number.isSafeInteger(serial)||serial<0||serial>999999||!linearChallenges.some(([c])=>c===challenge))return null;
 const rates={revisit:[.5,0,-.5,1,-1,1.5,-2,2],unknown:[.5,-.5,1,-1,1.5,-1.5,2,-2],contrast:[.5,0,-.5,1,-1,1.5,-1.5,2]};
 const k=serial%48,t=2+Math.floor(k/16),m=rates[challenge][Math.floor(k/2)%8],minimum=m<0?Math.max(0,-6-6*m):m===0?4:-3;
 const b=(challenge==='contrast'?Math.max(minimum,-6-6*(m-.5)-t/2):minimum)+k%2,value=x=>m*x+b,target=value(t),rate=q(m),start=q(b),rule=`y = (${rate}) × x + (${start})`,label=linearChallenges.find(([c])=>c===challenge)[1];
 const direction=m<0?`lowers the balance by ${q(-m)} net tokens`:m===0?'leaves the balance unchanged':`raises the balance by ${rate} net tokens`;
 const model={m:rate,b:start,title:`Balance A · ${rule}`,xUnit:'turns',yUnit:'net tokens'};
 const teach=[`A fictional token account starts at ${start} net tokens. Negative balances mean tokens owed, never a negative count of objects. Each turn ${direction}. Inputs are whole turns from 0 to 6.`,`In ${rule}, x counts turns and y is the net balance. The signed rate m is ${rate} net tokens per turn; the start b is ${start} net tokens. At zero turns the balance equals the start. A two-turn change is ${q(2*m)} tokens, while the one-turn rate is ${rate}.`];
 teach.push('A positive rate increases the balance, a negative rate decreases it, and a zero rate keeps it steady. Rate and balance answer different questions. Zero rate does not require a zero starting balance.');
 if(m===0)teach.push(`With rate 0, every permitted whole-turn input from 0 to 6 gives the starting balance ${start}. Any different target balance is never reached in this model. There is no division by zero.`);
 const example=m<0?'Different model: y = (−5/2) × x + 9. At x = 6 the balance is −15 + 9 = −6. To reach −6, subtract 9 from BOTH sides, giving (−5/2)x = −15; divide BOTH sides by −5/2 to get x = 6. Substitute to check.':'Different model: y = (5/2) × x − 4. At x = 6 the balance is 15 − 4 = 11. To reach 11, add 4 to BOTH sides, giving (5/2)x = 15; divide BOTH sides by 5/2 to get x = 6. Substitute to check.';
 const source={id:`investigation-${serial}`,title:`Investigation ${serial+1} · ${label}`,idea:challenge==='contrast'?'Two rates and two starts determine where balances meet and which is greater.':challenge==='unknown'?'Change the unknown: undo the start and the rate to find a number of turns.':'Connect a starting balance and a signed per-turn change to an exact output.',teach,model,generation:{version:1,serial,challenge},items:[]};
 if(challenge==='revisit'){
  source.items=[item('guided',1,'Name this account’s rate and starting balance.',[f('m','Rate · net tokens per turn',m),f('b','Start · net tokens',b)],['Read the value at x = 0 for the start.','Compare neighboring outputs for the per-turn change.'],'The starting value and per-turn change answer different questions.',example,`The rate is ${rate} net tokens per turn and the start is ${start} net tokens.`),item('own',2,`What is the net balance at ${t} turns?`,[f('height','Net balance',target)],[`First multiply the rate ${rate} by ${t}.`,`Then add the signed starting balance ${start}.`],'A negative balance represents an amount owed. Combine the signed per-turn changes with the starting balance.',example,`${rule} at x = ${t} gives ${q(m*t)} + (${start}) = ${q(target)} net tokens.`),item('return',3,'Separate a total change from the starting value.',[f('change','Change over TWO turns',2*m),f('b','Starting balance',b)],['Two turns combine two equal signed one-turn changes.'],'The two-turn change is twice the signed rate; the start remains the value at zero turns.',example,`Two turns change the balance by ${q(2*m)}; the start remains ${start}.`)];
 }else if(challenge==='unknown'){
  teach.push(`To reach ${q(target)}, solve (${rate})x + (${start}) = ${q(target)}. Subtract the signed start (${start}) from BOTH sides: (${rate})x = ${q(m*t)}. Divide BOTH sides by ${rate}; then substitute the resulting input into the original rule. Subtracting a negative start adds its opposite.`);
  source.items=[item('guided',1,`Use the rule to find the balance at ${t} turns.`,[f('height','Net balance',target)],[`Multiply ${rate} by ${t}, then add (${start}).`],'Keep change and starting balance separate.',example,`The output is ${q(target)} net tokens.`),item('own',2,`How many turns reach a net balance of ${q(target)}?`,[f('product','Right side after subtracting the signed start on BOTH sides',m*t),f('x','Number of turns x',t)],[],`Subtract (${start}) from both sides before dividing both sides by the rate ${rate}.`,example,`After subtracting (${start}), (${rate})x = ${q(m*t)}; dividing gives x = ${t}. Substitution gives ${q(target)}.`),item('return',3,`A different account changes by ${q(2*m)} net tokens over TWO turns. What is its one-turn rate?`,[f('m','Rate · net tokens per turn',m)],['A two-turn change combines two equal one-turn changes.'],'Divide the total change by the number of turns.',example,`${q(2*m)} ÷ 2 = ${rate} net tokens per turn.`)];
 }else{
  const m2=m-.5,b2=b+t/2,v2=x=>m2*x+b2;model.comparison={m:q(m2),b:q(b2),title:`Balance B · y = (${q(m2)}) × x + (${q(b2)})`};
  teach.push(`Account B starts at ${q(b2)} net tokens and changes by ${q(m2)} net tokens each turn. Its rule is y = (${q(m2)}) × x + (${q(b2)}). B starts ${q(t/2)} above A, while A’s signed rate is ${q(.5)} net tokens per turn greater.`,`Set the two expressions equal. Subtract B’s rate × x and A’s signed start from BOTH sides to obtain (1/2)x = ${q(t/2)}. Divide both sides by 1/2 and substitute in both original rules. Which balance is greater can change at the meeting input; a higher rate alone does not determine the larger output.`);
  const comparisonExample=m<=0?'Different pair: A = −x + 9; B = −2x + 14. Set equal: −x + 9 = −2x + 14. Add 2x and subtract 9 on BOTH sides: x = 5, both balances 4. At x = 4, A = 5 and B = 6; at x = 6, A = 3 and B = 2. Both accounts fall, but A falls less per turn.':'Different pair: A = 2x − 4; B = x + 1. Set equal: 2x − 4 = x + 1. Subtract x and add 4 on BOTH sides: x = 5, both balances 6. At x = 4, A = 4 and B = 5; at x = 6, A = 8 and B = 7.';
  source.items=[item('guided',1,'Name the two differences between the accounts.',[f('start','B start minus A start',t/2),f('rate','A rate minus B rate',.5)],['Subtract the signed starting values.','Subtract the rates using equal units.'],'The starting gap closes by the difference in rates each turn.',comparisonExample,`B starts ${q(t/2)} above A; A’s signed rate is 1/2 net tokens per turn greater.`),item('own',2,'At what input do the two balances meet?',[f('x','Meeting input · turns',t),f('height','Common net balance',target)],[],'Set the two original expressions equal. Do the same operation to BOTH sides, then substitute into BOTH rules.',comparisonExample,`(1/2)x = ${q(t/2)}, so x = ${t}. Both balances are ${q(target)}.`),item('return',3,`Compare on each side of the meeting: find both balances at ${t-1} and ${t+1} turns.`,[f('a-before',`A at ${t-1} turns`,value(t-1)),f('b-before',`B at ${t-1} turns`,v2(t-1)),f('a-after',`A at ${t+1} turns`,value(t+1)),f('b-after',`B at ${t+1} turns`,v2(t+1))],['Use each account’s own start and rate.','Compare the two outputs at the SAME input.'],'A lower balance can mean more debt. Do not choose by slope alone.',comparisonExample,`Before the meeting A = ${q(value(t-1))}, B = ${q(v2(t-1))}, so B is greater. After it A = ${q(value(t+1))}, B = ${q(v2(t+1))}, so A is greater.`)];
 }
 return source;
}
